import{_ as o,o as t,c as s,a2 as n}from"./chunks/framework.COxUneRg.js";const m=JSON.parse('{"title":"The design system and the brand live in the component workshop","description":"","frontmatter":{"status":"accepted","date":"2026-11-15T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0032-the-design-system-and-the-brand-live-in-the-component-workshop.md","filePath":"docs/adr/0032-the-design-system-and-the-brand-live-in-the-component-workshop.md"}'),a={name:"docs/adr/0032-the-design-system-and-the-brand-live-in-the-component-workshop.md"};function h(i,e,r,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="the-design-system-and-the-brand-live-in-the-component-workshop" tabindex="-1">The design system and the brand live in the component workshop <a class="header-anchor" href="#the-design-system-and-the-brand-live-in-the-component-workshop" aria-label="Permalink to &quot;The design system and the brand live in the component workshop&quot;">​</a></h1><p>The component workshop (<a href="./0028-storybook-is-the-component-workshop-of-the-design-system">ADR 0028</a>) is the home of the whole design system and of the brand: the design system rules, the tokens, the components, the screens (<a href="./0029-mockups-are-stories-in-the-component-workshop">ADR 0029</a>), Poulpy&#39;s rules and moods, his drawings, his 3D model, the brand book and the brand decisions. This amends ADR 0029, which kept the brand on the docs site.</p><p>The owner chose this on 15 November 2026, once every mockup was a story, so that a person finds everything about how Coach Poulpy looks and feels in one place, beside the components that draw it.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li><strong>The rules are Markdown files in the workshop&#39;s folder.</strong> <code>web/storybook/stories/design-system/design-system.md</code>, <code>web/storybook/stories/brand/brand.md</code>, <code>brand-decisions.md</code> and <code>poulpy-3d.md</code> are what agents read and what a PR changes. The workshop shows them one topic per page, cut at their second-level headings (<code>web/storybook/stories/markdown-pages.ts</code>), importing them directly rather than copying them in at build time, with the live parts beside them: the token swatches, the drawings, the turning 3D model and the brand book. A new section fails the workshop&#39;s build until it is given a page.</li><li><strong>The live parts move into the workshop.</strong> The 3D preview (<code>Poulpy3d.vue</code>, three.js) and the brand book (<code>brand-book/</code>) are under <code>web/storybook/stories/brand/</code>; the drawings page shows the Core &gt; Poulpy story.</li><li><strong>The docs site links to the workshop</strong> from its top menu, its home page and its Design system and Brand menus. It no longer publishes those four files as plain text (the owner decided this on 15 November 2026, amending the first version of this ADR): they live only in the workshop, so every guideline stays reachable from the docs site through its links to the workshop, and pages of the docs site link to the workshop pages. It keeps what is not design system or brand: architecture, decisions, specs, translations and the roadmap.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>One place to look: a reviewer reads a rule next to the component or drawing it governs, in light and dark.</li><li>One copy of each rule, in one place: the Markdown sits beside the pages that show it, and the docs site no longer carries a second, plain-text copy.</li><li>The live parts are checked: the workshop builds and tests them with the rest of the stories.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The docs site&#39;s Drawings, Poulpy in 3D and Brand book pages and their Vue components are gone; three.js is a dependency of the workshop instead of the site.</li><li>The 3D model&#39;s glTF files are linked from the repo on GitHub rather than downloaded from the site.</li></ul>',9)])])}const w=o(a,[["render",h]]);export{m as __pageData,w as default};
